@js:
var su=source.key,
so=su+"/e/search/index.php",
body=`show=title,writer&keyboard=${key}&tbname=news&tempid=1`;
head=JSON.parse(source.header);
res=java.post(so,body,head)
.header("location");
String(res).replace(/result.*searchid/,
"/e/search/result/index.php?page={{page-1}}&searchid")

ruleToc.chapterList:
@css:
#allchapter>.title, #allchapter>.details

@js:
list=[]
$=result
for(i in $){
if(String($[i]).match(/class="title/)){
	t=String($[i].text()).replace(new RegExp(book.name,''),'').replace(/（.*|\(.*/g,'');
		list.push({
				text: " 【"+t+" 】 ",
				volume: true
			})
	}
else{
		$[i].select("a").forEach(a=>{
				list.push({
						text: a.text(),
						href: a.attr("href")
					})
			})
	}
}
list

